import csv
import io
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 21
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )

    records = []
    try:
        for record in reader:
            records.append(record)
    except csv.Error:
        pass

    header_index = None
    fallback_index = None

    for index, record in enumerate(records):
        if not record or all(value.strip() == "" for value in record):
            continue

        first = record[0].lstrip("\ufeff").lstrip()
        if first.startswith("#"):
            continue

        if fallback_index is None:
            fallback_index = index
        if len(record) == expected_width:
            header_index = index
            break

    if header_index is None:
        header_index = fallback_index
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = []
    for record in records[header_index + 1:]:
        if not record:
            continue
        row = list(record)
        if len(row) < len(columns):
            row.extend([""] * (len(columns) - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
